package com.vyron.assistant;
import android.accessibilityservice.*;import android.graphics.Path;import android.os.Build;import android.view.accessibility.*;
public class VyronAccessibilityService extends AccessibilityService{static VyronAccessibilityService instance;protected void onServiceConnected(){super.onServiceConnected();instance=this;}public void onAccessibilityEvent(AccessibilityEvent e){}public void onInterrupt(){}public void onDestroy(){if(instance==this)instance=null;super.onDestroy();}public static boolean back(){return instance!=null&&instance.performGlobalAction(GLOBAL_ACTION_BACK);}public static boolean scroll(boolean down){if(instance==null)return false;AccessibilityNodeInfo root=instance.getRootInActiveWindow();if(root!=null){boolean b=find(root,down);root.recycle();if(b)return true;}if(Build.VERSION.SDK_INT>=24){Path p=new Path();p.moveTo(500,down?800:350);p.lineTo(500,down?350:800);return instance.dispatchGesture(new GestureDescription.Builder().addStroke(new GestureDescription.StrokeDescription(p,0,400)).build(),null,null);}return false;}static boolean find(AccessibilityNodeInfo n,boolean down){if(n.isScrollable()&&n.performAction(down?AccessibilityNodeInfo.ACTION_SCROLL_FORWARD:AccessibilityNodeInfo.ACTION_SCROLL_BACKWARD))return true;for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo c=n.getChild(i);if(c!=null){boolean b=find(c,down);c.recycle();if(b)return true;}}return false;}}
